#include <system_error>
#include <functional>
#include <sstream>
#include <cassert>
#include <iostream>

int main() {
    std::error_code error = std::make_error_code(std::errc::invalid_argument);
    assert(error);
    assert(error.value() != 0);
    assert(!error.message().empty());
    assert(error.category() == std::generic_category());
    std::error_code copy;
    copy.assign(error.value(), error.category());
    assert(copy == error);
    assert(std::hash<std::error_code>{}(copy) == std::hash<std::error_code>{}(error));
    copy.clear();
    assert(!copy);
    copy = std::make_error_code(std::errc::invalid_argument);
    assert(copy == error);
    assert(error.default_error_condition() == std::errc::invalid_argument);
    std::ostringstream text;
    text << error;
    assert(!text.str().empty());
    std::cout << "Checks passed\n";
}
